import math

solutions = []
known_solutions = {(3, 4), (4, 5)}

for a in range(11):
    for b in range(11):
        # Calculate the left side of the equation: 2^a * 5^b + 625
        try:
            LHS = (2**a) * (5**b) + 625
        except OverflowError:
            # Skip if the numbers become too large for standard integer types, although for a, b <= 10 this shouldn't happen
            continue

        # Check if LHS is a perfect square
        N = int(math.isqrt(LHS))
        if N * N == LHS:
            # Check if this solution is one of the previously found ones
            if (a, b) not in known_solutions:
                solutions.append((a, b, N))

print(f"New solutions found (a, b, N) for a, b in [0, 10] excluding (3, 4) and (4, 5):")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No new solutions found.")

def is_50_smooth(n):
    """Checks if n is of the form 2^p * 5^q."""
    if n <= 0:
        return False
    while n % 2 == 0:
        n //= 2
    while n % 5 == 0:
        n //= 5
    return n == 1

# Case d=50: X(X+1) must be 50-smooth.
print("--- Case X(X+1) is 50-smooth (d=50) ---")
consecutive_50_smooth = []
# Check up to X=100, should be plenty
for X in range(1, 101):
    if is_50_smooth(X * (X + 1)):
        consecutive_50_smooth.append((X, X+1, X*(X+1)))

print("Consecutive 50-smooth pairs found:")
for X, Y, product in consecutive_50_smooth:
    print(f"X={X}, Y={Y}, Product={product}")

# Case d=2: X(X+25) must be 50-smooth.
print("\n--- Case X(X+25) is 50-smooth (d=2) ---")
spaced_25_50_smooth = []
# Check up to X=50 (since X*X+25X ~ X^2, 50^2 = 2500, which is small enough)
for X in range(1, 51):
    if is_50_smooth(X * (X + 25)):
        spaced_25_50_smooth.append((X, X+25, X*(X+25)))

print("Pairs separated by 25, whose product is 50-smooth:")
for X, Y, product in spaced_25_50_smooth:
    print(f"X={X}, Y={Y}, Product={product}")
